//go:build integration && unix

// Integration tests against a disposable OpenSSH server on 127.0.0.1.
//
//	go test -tags integration ./sshutil/
//
// They need sshd, ssh and ssh-keygen in PATH (or /usr/sbin/sshd) and log in
// as the current user. Only synthetic keys generated by the test are used;
// the server, keys and client config live in t.TempDir().
package sshutil

import (
	"bytes"
	"fmt"
	"net"
	"os"
	"os/exec"
	"os/user"
	"path/filepath"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/sshman-org/sshman/model"
	"golang.org/x/crypto/ssh"
)

type lab struct {
	t          *testing.T
	dir        string
	port       int
	user       string
	authKeys   string
	knownHosts string
	sshConfig  string
	wrapper    string
	hostKey    string
	sshd       *exec.Cmd
	logBuf     *syncBuffer
}

// syncBuffer is a goroutine-safe buffer for the sshd log.
type syncBuffer struct {
	mu sync.Mutex
	b  bytes.Buffer
}

func (s *syncBuffer) Write(p []byte) (int, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.b.Write(p)
}

func (s *syncBuffer) String() string {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.b.String()
}

func (l *lab) log() string { return l.logBuf.String() }

func findSSHD() string {
	if p, err := exec.LookPath("sshd"); err == nil {
		return p
	}
	for _, p := range []string{"/usr/sbin/sshd", "/usr/local/sbin/sshd"} {
		if _, err := os.Stat(p); err == nil {
			return p
		}
	}
	return ""
}

func freePort(t *testing.T) int {
	l, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	defer l.Close()
	return l.Addr().(*net.TCPAddr).Port
}

func newLab(t *testing.T, clientConfig string) *lab {
	t.Helper()
	sshd := findSSHD()
	if sshd == "" {
		t.Skip("sshd not installed")
	}
	if _, err := exec.LookPath("ssh"); err != nil {
		t.Skip("ssh not installed")
	}
	u, err := user.Current()
	if err != nil {
		t.Fatal(err)
	}
	dir, err := os.MkdirTemp("", "sshman-it-")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.RemoveAll(dir) })
	_ = os.Chmod(dir, 0o755) // sshd StrictModes walks parent dirs
	l := &lab{t: t, dir: dir, port: freePort(t), user: u.Username}
	l.hostKey = filepath.Join(dir, "hostkey")
	run(t, "ssh-keygen", "-q", "-t", "ed25519", "-N", "", "-f", l.hostKey)
	// The remote HOME is a lab directory (SetEnv below) so sendkey never
	// touches the real ~/.ssh of the user running the tests.
	home := filepath.Join(dir, "home")
	if err := os.MkdirAll(filepath.Join(home, ".ssh"), 0o700); err != nil {
		t.Fatal(err)
	}
	l.authKeys = filepath.Join(home, ".ssh", "authorized_keys")
	if err := os.WriteFile(l.authKeys, nil, 0o600); err != nil {
		t.Fatal(err)
	}
	cfg := filepath.Join(dir, "sshd_config")
	writeFile(t, cfg, fmt.Sprintf(`Port %d
ListenAddress 127.0.0.1
HostKey %s
PidFile %s/sshd.pid
AuthorizedKeysFile %s
PubkeyAuthentication yes
PasswordAuthentication no
KbdInteractiveAuthentication no
PermitRootLogin prohibit-password
AllowAgentForwarding yes
StrictModes no
UsePAM no
LogLevel VERBOSE
SetEnv HOME=%s
`, l.port, l.hostKey, dir, l.authKeys, home))
	l.sshd = exec.Command(sshd, "-D", "-e", "-f", cfg)
	logBuf := &syncBuffer{}
	l.logBuf = logBuf
	l.sshd.Stderr = logBuf
	if err := l.sshd.Start(); err != nil {
		t.Fatalf("start sshd: %v", err)
	}
	t.Cleanup(func() {
		_ = l.sshd.Process.Kill()
		_ = l.sshd.Wait()
		if t.Failed() {
			t.Logf("sshd log:\n%s", logBuf.String())
		}
	})
	deadline := time.Now().Add(10 * time.Second)
	for {
		c, err := net.Dial("tcp", fmt.Sprintf("127.0.0.1:%d", l.port))
		if err == nil {
			c.Close()
			break
		}
		if time.Now().After(deadline) {
			t.Fatalf("sshd did not start: %s", logBuf.String())
		}
		time.Sleep(50 * time.Millisecond)
	}
	l.knownHosts = filepath.Join(dir, "known_hosts")
	l.sshConfig = filepath.Join(dir, "ssh_config")
	l.setClientConfig(clientConfig)
	// The wrapper isolates the client from the real ~/.ssh: a private
	// config (-F) and known_hosts. sshman's own options follow and win.
	l.wrapper = filepath.Join(dir, "ssh-wrapper")
	writeFile(t, l.wrapper, fmt.Sprintf("#!/bin/sh\nexec ssh -F %s -o UserKnownHostsFile=%s -o GlobalKnownHostsFile=/dev/null -o BatchMode=yes \"$@\"\n", l.sshConfig, l.knownHosts))
	_ = os.Chmod(l.wrapper, 0o755)
	return l
}

func (l *lab) setClientConfig(extra string) {
	writeFile(l.t, l.sshConfig, "Host *\n  LogLevel ERROR\n"+extra)
}

func (l *lab) trustHostKey() {
	pub, err := os.ReadFile(l.hostKey + ".pub")
	if err != nil {
		l.t.Fatal(err)
	}
	writeFile(l.t, l.knownHosts, fmt.Sprintf("[127.0.0.1]:%d %s", l.port, pub))
}

func (l *lab) entry(t *testing.T, name string, authorize bool) *model.Entry {
	t.Helper()
	priv, pub := genEd25519(t, "")
	if authorize {
		f, err := os.OpenFile(l.authKeys, os.O_APPEND|os.O_WRONLY, 0o600)
		if err != nil {
			t.Fatal(err)
		}
		_, _ = f.Write(ssh.MarshalAuthorizedKey(pub))
		f.Close()
	}
	return &model.Entry{Name: name, User: l.user, Host: "127.0.0.1", Port: l.port, Key: string(priv)}
}

func (l *lab) connect(e *model.Entry, opts Options, remote ...string) (string, string, error) {
	var out, errb bytes.Buffer
	opts.SSHPath = l.wrapper
	opts.RemoteCommand = remote
	opts.Stdin = strings.NewReader("")
	opts.Stdout, opts.Stderr = &out, &errb
	err := Connect(e, opts)
	return out.String(), errb.String(), err
}

func run(t *testing.T, name string, args ...string) {
	t.Helper()
	if out, err := exec.Command(name, args...).CombinedOutput(); err != nil {
		t.Fatalf("%s %v: %v\n%s", name, args, err, out)
	}
}

func writeFile(t *testing.T, p, s string) {
	t.Helper()
	if err := os.WriteFile(p, []byte(s), 0o600); err != nil {
		t.Fatal(err)
	}
}

// Q-02: with no identities in ~/.ssh at all, connect authenticates with the
// vault key through the session agent.
func TestIntegrationConnectUsesVaultKey(t *testing.T) {
	l := newLab(t, "")
	l.trustHostKey()
	e := l.entry(t, "a", true)
	out, errs, err := l.connect(e, Options{}, "echo", "AUTH_OK")
	if err != nil || !strings.Contains(out, "AUTH_OK") {
		t.Fatalf("connect failed: %v\nstdout=%s\nstderr=%s", err, out, errs)
	}
	// An unauthorised vault key must fail (the agent offers only that key).
	other := l.entry(t, "b", false)
	if _, _, err := l.connect(other, Options{}, "true"); err == nil {
		t.Fatal("unauthorised key logged in")
	}
}

// S-01: even with "ForwardAgent yes" in the user's config, the remote host
// cannot reach the vault-backed agent.
func TestIntegrationNoAgentForwarding(t *testing.T) {
	if _, err := exec.LookPath("ssh-add"); err != nil {
		t.Skip("ssh-add not installed")
	}
	l := newLab(t, "  ForwardAgent yes\n")
	l.trustHostKey()
	e := l.entry(t, "a", true)
	out, errs, err := l.connect(e, Options{}, `echo "SOCK=[$SSH_AUTH_SOCK]"; ssh-add -l; echo "RC=$?"`)
	if err != nil {
		t.Fatalf("connect: %v %s", err, errs)
	}
	if !strings.Contains(out, "SOCK=[]") {
		t.Fatalf("remote has an agent socket:\n%s", out)
	}
	if strings.Contains(out, "ED25519") || strings.Contains(out, "RC=0") {
		t.Fatalf("vault key reachable from remote:\n%s", out)
	}
}

// A user IdentityAgent pointing elsewhere must not redirect authentication.
func TestIntegrationUserIdentityAgentIgnored(t *testing.T) {
	l := newLab(t, "  IdentityAgent /nonexistent/agent.sock\n  IdentityFile /nonexistent/key\n")
	l.trustHostKey()
	e := l.entry(t, "a", true)
	if out, errs, err := l.connect(e, Options{}, "echo", "AUTH_OK"); err != nil || !strings.Contains(out, "AUTH_OK") {
		t.Fatalf("connect: %v %s %s", err, out, errs)
	}
}

// S-05: unknown host keys are not silently accepted unless requested, and a
// changed host key is always refused.
func TestIntegrationHostKeyPolicy(t *testing.T) {
	l := newLab(t, "  StrictHostKeyChecking yes\n")
	e := l.entry(t, "a", true)
	if _, _, err := l.connect(e, Options{}, "true"); err == nil {
		t.Fatal("unknown host key accepted with StrictHostKeyChecking yes")
	}
	if b, _ := os.ReadFile(l.knownHosts); len(b) != 0 {
		t.Fatal("known_hosts modified")
	}
	// Explicit opt-in: accept-new pins the key.
	l.setClientConfig("")
	if out, errs, err := l.connect(e, Options{AcceptNewHostKey: true}, "echo", "OK"); err != nil || !strings.Contains(out, "OK") {
		t.Fatalf("accept-new: %v %s", err, errs)
	}
	// Simulate a MITM: known_hosts holds a different key.
	other := filepath.Join(l.dir, "otherhost")
	run(t, "ssh-keygen", "-q", "-t", "ed25519", "-N", "", "-f", other)
	pub, _ := os.ReadFile(other + ".pub")
	writeFile(t, l.knownHosts, fmt.Sprintf("[127.0.0.1]:%d %s", l.port, pub))
	if _, errs, err := l.connect(e, Options{AcceptNewHostKey: true}, "true"); err == nil {
		t.Fatalf("changed host key accepted: %s", errs)
	}
}

// Q-04/S-13: sendkey installs a second key using an already authorised vault
// key, exactly once, and the new key then works.
func TestIntegrationSendKeyViaAndIdempotent(t *testing.T) {
	l := newLab(t, "")
	l.trustHostKey()
	old := l.entry(t, "old", true)
	newE := l.entry(t, "new", false)
	opts := Options{SSHPath: l.wrapper, Stdin: strings.NewReader(""), Stdout: &bytes.Buffer{}, Stderr: &bytes.Buffer{}}
	for range 2 {
		if err := SendPublicKey(newE, old, opts); err != nil {
			t.Fatalf("sendkey: %v %s", err, opts.Stderr)
		}
	}
	b, _ := os.ReadFile(l.authKeys)
	if n := strings.Count(string(b), "\n"); n != 2 {
		t.Fatalf("authorized_keys has %d lines, want 2:\n%s", n, b)
	}
	if out, errs, err := l.connect(newE, Options{}, "echo", "NEW_OK"); err != nil || !strings.Contains(out, "NEW_OK") {
		t.Fatalf("new key: %v %s", err, errs)
	}
}

// Session cleanup: no socket directory is left behind.
func TestIntegrationSessionCleanup(t *testing.T) {
	l := newLab(t, "")
	l.trustHostKey()
	e := l.entry(t, "a", true)
	before, _ := filepath.Glob(filepath.Join(os.TempDir(), "sshman-*", "agent.sock"))
	if _, _, err := l.connect(e, Options{}, "true"); err != nil {
		t.Fatal(err)
	}
	after, _ := filepath.Glob(filepath.Join(os.TempDir(), "sshman-*", "agent.sock"))
	if len(after) > len(before) {
		t.Fatalf("session directory left behind: %v", after)
	}
}

// R-3 / D-08: with ProxyJump, the jump hop runs as a separate ssh process
// that does not receive sshman's -o options. The vault key must still never
// be offered to (or forwarded through) the jump host, even with
// "ForwardAgent yes" configured for both hops; it is used only for the
// final destination, through the tunnel.
func TestIntegrationProxyJump(t *testing.T) {
	t.Setenv("SSH_AUTH_SOCK", "") // no user agent: only sshman's could help
	l := newLab(t, "")
	l.trustHostKey()
	vaultEntry := l.entry(t, "target", true) // vault key authorised on the server

	// The jump hop gets its own key from the user's ssh config.
	jumpKey := filepath.Join(l.dir, "jumpkey")
	run(t, "ssh-keygen", "-q", "-t", "ed25519", "-N", "", "-C", "jump", "-f", jumpKey)
	jumpCfg := func(jumpIdentity string) string {
		return fmt.Sprintf(`Host jump
  HostName 127.0.0.1
  Port %d
  User %s
%s  ForwardAgent yes
Host target
  HostName 127.0.0.1
  Port %d
  ProxyJump jump
  ForwardAgent yes
Host *
  UserKnownHostsFile %s
  GlobalKnownHostsFile /dev/null
  BatchMode yes
`, l.port, l.user, jumpIdentity, l.port, l.knownHosts)
	}
	// No identity for the jump at all: an agent is the only thing that
	// could authenticate it, so this fails if sshman's agent leaks to it.
	l.setClientConfig(jumpCfg(""))
	vaultEntry.Host, vaultEntry.Port = "target", 0

	// 1. Jump key not authorised: the hop must fail, proving the vault key
	//    is not available to the jump ssh process.
	if out, errs, err := l.connect(vaultEntry, Options{}, "echo", "SHOULD_NOT_RUN"); err == nil || strings.Contains(out, "SHOULD_NOT_RUN") {
		t.Fatalf("jump hop authenticated without its own key (vault key exposed to ProxyJump?)\nstdout=%s\nstderr=%s", out, errs)
	}

	// 2. Authorise the jump key: the session works end to end and the
	//    destination still has no forwarded agent.
	pub, err := os.ReadFile(jumpKey + ".pub")
	if err != nil {
		t.Fatal(err)
	}
	f, err := os.OpenFile(l.authKeys, os.O_APPEND|os.O_WRONLY, 0o600)
	if err != nil {
		t.Fatal(err)
	}
	_, _ = f.Write(pub)
	f.Close()
	l.setClientConfig(jumpCfg("  IdentityFile " + jumpKey + "\n  IdentitiesOnly yes\n"))
	out, errs, err := l.connect(vaultEntry, Options{}, `echo "JUMP_OK SOCK=[$SSH_AUTH_SOCK]"; ssh-add -l; echo "RC=$?"`)
	if err != nil || !strings.Contains(out, "JUMP_OK") {
		t.Fatalf("connect via ProxyJump failed: %v\nstdout=%s\nstderr=%s", err, out, errs)
	}
	if !strings.Contains(out, "SOCK=[]") || strings.Contains(out, "RC=0") {
		t.Fatalf("destination reached an agent through the jump:\n%s", out)
	}
	// The destination must have been authenticated with the vault key, the
	// jump with its own key.
	logb := l.log()
	vfp := ssh.FingerprintSHA256(mustPub(t, vaultEntry.Key))
	jfp := fingerprintFile(t, jumpKey+".pub")
	if !strings.Contains(logb, "Accepted publickey for "+l.user) || !strings.Contains(logb, vfp) || !strings.Contains(logb, jfp) {
		t.Fatalf("expected both keys in the server log (vault %s, jump %s):\n%s", vfp, jfp, logb)
	}
}

func mustPub(t *testing.T, privPEM string) ssh.PublicKey {
	t.Helper()
	s, err := ssh.ParsePrivateKey([]byte(privPEM))
	if err != nil {
		t.Fatal(err)
	}
	return s.PublicKey()
}

func fingerprintFile(t *testing.T, path string) string {
	t.Helper()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	pub, _, _, _, err := ssh.ParseAuthorizedKey(b)
	if err != nil {
		t.Fatal(err)
	}
	return ssh.FingerprintSHA256(pub)
}
